import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-transformacion-del-aguila-iv', 'B',
 [dict(t=1514, e=1606, titulo='Andar con Dios es acudir y crecer', txt='Dice que Enoc anduvo con Dios hasta que Dios se lo llevó. Lo agradó de tal manera que desapareció; no lo volvieron a ver. Esa palabra «anduvo» viene de la palabra […], que quiere decir acudir. ¿Por qué se pudo ir Enoc? Porque acudió siempre a Dios. Porque cuando tenía necesidad se acercaba a él. También quiere decir alcanzar. No se quedó ahí: alcanzó, por lo cual fue llamado. Quiere decir que de hoy en adelante usted tiene que arrebatar las cosas de Dios. Otra cosa: crecer. Andar con Dios es crecer espiritualmente. No te puedes quedar con dos versículos y que no los vivas, o tener un gran conocimiento y no vivirlo.'),
  dict(t=1901, e=1984, titulo='Bájate del árbol del orgullo', txt='En Lucas 19:8 dice: «Y Zaqueo, puesto en pie…». Pero antes de ponerse en pie, estaba en un árbol arriba, viendo al Señor, y el Señor lo vio y le dijo: «Zaqueo, hoy tengo que estar en tu casa». Miren qué privilegio, hermano. ¿Por qué estaba en las alturas Zaqueo? Porque era chaparrito, dice. Pero aparte de que era chaparrito, era orgulloso. Miraba a los demás por arriba, y el Señor le dijo: «Para poderte bendecir, Zaqueo, voy a ir a tu casa. Bájate ese orgullo para que yo pueda entrar». A veces el Señor no nos visita porque somos una partida de orgullosos todos, pero el Señor va a tener misericordia de tu casa y de tu vida y te va a decir: «Yo quiero ir a tu casa. Bájate del árbol, quita todo orgullo, humíllate». Es que cuesta, hermano. A la gente le gusta el orgullo porque es una manera de defenderse.'),
  dict(t=3943, e=4033, titulo='Un corazón dedicado por entero', txt='Tengamos cuidado con envejecer un ministerio dentro de nosotros, porque dice que se va renovando día con día; pero aquí Salomón, en vez de renovarlo, iba envejeciendo. Y dice: «Pues sucedió que cuando Salomón era ya viejo, sus mujeres desviaron su corazón tras otros dioses». […] Entonces, cuando te vuelves viejo en las cosas del mundo, hermano, dice: «Y su corazón no estuvo dedicado». Tienes que dedicar tu corazón a Dios por entero, al Señor tu Dios, como había estado el corazón de David, su padre. David cometió muchos errores, pero él se arrepentía, se ponía cuentas, iba para adelante.')],
 [dict(t=1502, txt='No es lo mismo andar con Dios que andar usted como le dé la gana y que Dios lo bendiga todos los días de su vida por ser cristiano.'),
  dict(t=2410, txt='Si entendemos por qué estamos aquí, hasta el abanicazo que usted se hace lo va a hacer con gozo.'),
  dict(t=4421, txt='El orden de Dios es lo que te hace feliz, porque el orden me trae bendición.')],
 ['Enoc acudía a Dios cada vez que tenía necesidad: ¿a quién o a qué acudes tú primero cuando algo te hace falta?',
  'Zaqueo tuvo que bajarse del árbol para recibir al Señor: ¿qué orgullo necesitas bajar de tu vida esta semana?',
  '¿Cómo estás cuidando que tu corazón siga dedicado por entero al Señor y no se vaya envejeciendo en las cosas del mundo?'],
 inicio=1082)
